import{_ as n,a as t,b as r,c as i,d as s,e as a,f as d,g as l,h as o,i as u,j as h,k as c,l as g,m as b,n as p}from"./chunks/events.DR5ZB87j.js";import{_ as k,o as m,c as f,a3 as w}from"./chunks/framework.BlfGB29P.js";const F=JSON.parse('{"title":"USB Extender für Home Assistant","description":"USB-Tasten, Stream Decks und Makropads über bis zu drei MQTT-Broker verbinden. Installation, Anlernen, Topics und Praxistest mit Bildern.","frontmatter":{"title":"USB Extender für Home Assistant","description":"USB-Tasten, Stream Decks und Makropads über bis zu drei MQTT-Broker verbinden. Installation, Anlernen, Topics und Praxistest mit Bildern."},"headers":[],"relativePath":"projects/usb-extender/index.md","filePath":"projects/usb-extender/index.md","lastUpdated":1795870835000}'),T={name:"projects/usb-extender/index.md"};function B(S,e,z,D,v,A){return m(),f("div",null,[...e[0]||(e[0]=[w('<h1 id="usb-extender-fur-home-assistant" tabindex="-1">USB Extender für Home Assistant <a class="header-anchor" href="#usb-extender-fur-home-assistant" aria-label="Permalink to &quot;USB Extender für Home Assistant&quot;">​</a></h1><p><strong>0.1.38 · Öffentliches Testrelease · Raspberry Pi · Stand 23. November 2026</strong></p><p>Eine USB-Tastatur am Raspberry Pi kann zum Bedienteil für Home Assistant oder ioBroker werden. Der USB Extender erkennt Eingaben und sendet sie über MQTT an bis zu <strong>drei Broker gleichzeitig</strong>. Die Weboberfläche dient zum Einrichten und kann danach abgeschaltet werden; USB und MQTT laufen unabhängig weiter.</p><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant" target="_blank" rel="noreferrer">GitHub / README DE und EN</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/releases/tag/v0.1.38" target="_blank" rel="noreferrer">ZIP 0.1.38 und SHA256</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">Änderungen</a></p><p>Dies ist ein eigenständiges Raspberry-Pi-Programm, keine HA-App zum Installieren im App-Store und keine offizielle Software von Home Assistant oder Elgato. Es ist <strong>kein USB-over-IP-Tunnel</strong>: Drucker oder Kameras werden damit nicht als entfernte USB-Geräte an HA durchgereicht.</p><p>Die Bilder stammen aus dem echten Nutzeraufbau mit 0.1.5. Die Oberfläche ist derzeit deutsch. Breite Bilder lassen sich durch Anklicken in Originalgröße öffnen.</p><p><a href="/images/usb-extender/key-list.png"><img src="'+n+'" alt="Breite Tastenliste mit MQTT-Kanälen"></a></p><h2 id="release-038" tabindex="-1">Neu in 0.1.38: MQTT-Systemsteuerung und HA-Kartenpaket <a class="header-anchor" href="#release-038" aria-label="Permalink to &quot;Neu in 0.1.38: MQTT-Systemsteuerung und HA-Kartenpaket {#release-038}&quot;">​</a></h2><p>Die Weboberfläche lässt sich jetzt auch bei abgeschaltetem Webdienst per MQTT starten und stoppen. <strong>Web-Autostart</strong>, <strong>Backup</strong> und <strong>Statusabfrage</strong> sind ebenfalls verfügbar. Unter <strong>MQTT-Broker</strong> die Systemsteuerung ausdrücklich für den gewünschten Broker einschalten und speichern; vorhandene Broker bleiben zunächst unverändert. Mit aktiver HA-Discovery entstehen zwei Schalter, ein Backup-Button und zwei Statussensoren unter dem Gerät <strong>USB Extender</strong>.</p><p>Befehle verwenden <code>usb-extender/global/web/set</code> und <code>usb-extender/global/web/autorun/set</code> mit <code>ON/OFF</code>; Backup und Statusabfrage verwenden <code>usb-extender/global/backup/set</code> bzw. <code>usb-extender/global/web/status/set</code> mit <code>PRESS</code>. Getrennte Rückmeldungen liegen unter <code>usb-extender/global/state/</code>: <code>webrun</code>, <code>autorun</code>, <code>state</code> und <code>backup</code>. Keine Retain-Befehle senden. <strong>Mehrere Extender am selben Broker reagieren auf diese globalen Topics gemeinsam.</strong><a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/v0.1.38/docs/mqtt-system-control.md" target="_blank" rel="noreferrer">Einrichtung und genaue Rückmeldungen</a>.</p><h3 id="cards" tabindex="-1">USB Extender Cards 0.1.0 <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;USB Extender Cards 0.1.0 {#cards}&quot;">​</a></h3><p>Das eigenständige <a href="https://github.com/rockbaer2007/usb-extender-cards" target="_blank" rel="noreferrer">Kartenpaket auf GitHub</a> bietet <strong>Mushroom- und Bubble-inspirierte Darstellung</strong> ohne zusätzliche Installation dieser Karten. Über HACS als benutzerdefiniertes Dashboard-Repository installieren oder die JavaScript-Datei aus dem <a href="https://github.com/rockbaer2007/usb-extender-cards/releases/tag/v0.1.0" target="_blank" rel="noreferrer">Release mit ZIP</a> manuell einbinden. Im visuellen Editor <strong>Automatisch zuordnen</strong>, Webadresse eintragen und Darstellung wählen. Entity-IDs werden aus der Registry gelesen; bei mehreren Extendern das Gerät ausdrücklich auswählen.</p><p><strong>Webfrontend öffnen</strong> öffnet beim Klick einen Wartetab, fordert den Start an und lädt die URL erst nach bestätigter Rückmeldung. Dazu kommen Web-/Autostart-Schalter, Backup und Statusanzeige. Bei blockierten Popups gibt es einen manuellen Link. Die Karte verwendet die bestehende HA-Sitzung, keinen zusätzlichen Token. Der Pi-Installer ändert kein Dashboard; im Systembereich steht ein Paketverweis.</p><p><a href="/images/usb-extender/cards-mushroom.png"><img src="'+t+'" alt="Mushroom-Darstellung mit simulierten HA-Entitäten"></a><a href="/images/usb-extender/cards-bubble.png"><img src="'+r+'" alt="Bubble-Darstellung mit simulierten HA-Entitäten"></a></p><p>Die Bilder zeigen lokale Vorschauen. Kartenlogik und Browserabläufe wurden mit simulierten HA-Entitäten geprüft; ein neuer Praxistest auf HA oder in der Companion-App steht aus. Die Oberfläche der Karte unterstützt DE/EN/FR.</p><h2 id="release-036" tabindex="-1">Bereits in 0.1.36: USB-Laufwerke kompakt anzeigen <a class="header-anchor" href="#release-036" aria-label="Permalink to &quot;Bereits in 0.1.36: USB-Laufwerke kompakt anzeigen {#release-036}&quot;">​</a></h2><p>USB-Sticks und andere USB-Massenspeicher werden anhand ihrer USB-Geräte- bzw. Interface-Klasse erkannt. Neue Laufwerke übernehmen keine ausgewählten MQTT-Ziele; Eingaben sind standardmäßig nicht freigegeben. Unpassende Eingabe-, Display- und Neuzuordnungsfelder werden bei Laufwerken ausgeblendet.</p><p>Unter <strong>USB / Virtuelle Geräte</strong> gibt es zwei Checkboxen:</p><ul><li><strong>System:</strong> eingeklappt erscheinen nur Gerätename und <strong>Systemlaufwerk</strong>.</li><li><strong>Hidden:</strong> eingeklappt erscheint nur der Gerätename.</li></ul><p>Beide schließen sich gegenseitig aus. Zum Bearbeiten die Zeile aufklappen; die Auswahl anschließend mit <strong>Speichern</strong> sichern. Ohne beide Markierungen startet der Eintrag geöffnet. Die Klassifizierung bleibt auch beim gespeicherten Offline-Gerät verfügbar. <strong>System ist eine manuelle Markierung</strong>, keine automatische Erkennung der Bootpartition. Hidden entfernt das Gerät nicht aus der Liste.</p><p>Diese Optionen ändern nur die Anzeige. Es werden keine Laufwerke eingehängt, formatiert oder beschrieben. Bestehende MQTT-Ziele und Belegungen sowie andere Geräte und Mobile-Kopplungen bleiben erhalten. Die Anzeige des freien Speicherplatzes im Kopf bezieht sich weiterhin auf das Dateisystem des Programm-Datenordners.</p><h2 id="release-035" tabindex="-1">Bereits in 0.1.35: Barcode-/QR-Scanner und HA-Tags <a class="header-anchor" href="#release-035" aria-label="Permalink to &quot;Bereits in 0.1.35: Barcode-/QR-Scanner und HA-Tags {#release-035}&quot;">​</a></h2><p>USB-HID-Tastaturscanner erhalten einen eigenen, zunächst ausgeschalteten Modus. Unter <strong>USB / Virtuelle Geräte</strong> das Gerät freigeben, Scanner-Modus aktivieren, <strong>DE/US-Layout</strong>, Abschluss <strong>Enter/Tab/Scanpause</strong>, eigenes Topic und Zielbroker wählen, dann speichern. Beispiel: <code>barcodescanner</code>. Eine Pause von 500 ms ist vorbelegt; lange oder unvollständige Eingaben werden verworfen. Serielle Scanner, beliebige Unicode-Eingaben und GS1-Steuersequenzen sind nicht unterstützt.</p><p>Jeder vollständige Scan wird als reiner Text ohne Retain gesendet. Gleiche Codes lösen bei jedem Scan erneut aus; vom Gerät gelieferte führende Nullen bleiben erhalten. QR-Links werden nicht geöffnet und enthaltene Befehle nicht ausgeführt. Die Vorschau zeigt den letzten Rohtext. Vorhandene Tastenaktionen dieses Geräts pausieren im Scanner-Modus; ihre Belegungen bleiben gespeichert.</p><h3 id="scanner-ha" tabindex="-1">Wo kommen die Scans in Home Assistant an? <a class="header-anchor" href="#scanner-ha" aria-label="Permalink to &quot;Wo kommen die Scans in Home Assistant an? {#scanner-ha}&quot;">​</a></h3><p>Am HA-Zielbroker Discovery einschalten. Der Scanner wird über die native <a href="https://www.home-assistant.io/integrations/tag.mqtt/" target="_blank" rel="noreferrer">MQTT-Tag-Integration</a> angemeldet. Scans erscheinen als <strong><code>tag_scanned</code>-Ereignisse</strong>, nicht als normale Sensorentitäten. Unter <strong>Einstellungen → Tags</strong> den Tag benennen und eine Tag-Automation anlegen, etwa zum Umschalten einer Lampe. Die Aktion wird in HA festgelegt. Dafür braucht USB Extender keinen HA-Zugriffstoken.</p><p>Optional wird <code>https://www.home-assistant.io/tag/werkstattlicht</code> als Tag-ID <code>werkstattlicht</code> gesendet. Andere Texte bleiben unverändert. ioBroker erhält auf dem gewählten Topic den Textwert; dort kann Discovery ausgeschaltet bleiben.</p><h3 id="scanner-test" tabindex="-1">Erfolgreicher Aplic-305045-Praxistest <a class="header-anchor" href="#scanner-test" aria-label="Permalink to &quot;Erfolgreicher Aplic-305045-Praxistest {#scanner-test}&quot;">​</a></h3><p>Am <strong>22. November 2026</strong> wurden auf Raspberry Pi .112 mit 0.1.35 vier echte Scans ausgeführt: Barcode zweimal, Text-QR und HA-Tag-QR. Jeder Scan wurde an drei Broker übergeben; auf HA .193 wurden vier getrennte native Ereignisse empfangen. ioBroker-Empfang auf <code>barcodescanner</code> ist ebenfalls bestätigt. Wiederholte Codes werden nicht verschluckt. Abschluss: USB-/MQTT- und Webdienst aktiv, keine Neustarts oder gemeldeten Fehler. Keine HA-Aktion wurde beim Test ausgeführt.</p><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/v0.1.35/docs/tests/scanner-live-0.1.35-20261122.md" target="_blank" rel="noreferrer">Vollständiger Test und Prüfgrenzen</a>. Die vor Beginn geprüfte Sicherung war beim Abschlussvergleich nicht mehr am aufgezeichneten Pfad; ein abschließender Hashnachweis der Metadaten ist daher nicht Bestandteil dieses Tests. Einstellungen und Kopplungen wurden vom Agenten nicht verändert. Neustart-/Abschaltprüfung der Scanner-Discovery bleibt ergänzend offen.</p><h3 id="values-gamepad" tabindex="-1">Weitere enthaltene Funktionen aus 0.1.32–0.1.34 <a class="header-anchor" href="#values-gamepad" aria-label="Permalink to &quot;Weitere enthaltene Funktionen aus 0.1.32–0.1.34 {#values-gamepad}&quot;">​</a></h3><ul><li><strong>Logitech Touchpad T650:</strong> acht einzeln aktivierbare Richtungswerte und X/Y mit eigenen Topics und HA-Sensoren, reine Zahlen 0–100. Alle zehn Live-Werte auf HA bestätigt.</li><li><strong>Alternativer Flächenmodus:</strong> fünf senkrechte Regler. Aufsetzen wählt den Streifen, der bis zum Abheben fest bleibt; oben 100, unten 0. Richtungsaktionen pausieren, ihre Einstellungen bleiben erhalten. X/Y bleibt unabhängig. Aktive Regler sind türkis, Richtungen goldfarben, pausierte Bereiche grau; Werte und letzter Trigger werden sichtbar. Fünf echte Werte in ioBroker bestätigt.</li><li><strong>DragonRise-Gamepad <code>0079:0006</code>:</strong> linker Stick <code>ABS_X/ABS_Y</code>, rechter Stick <code>ABS_RX/ABS_RZ</code>, je 0–100 und Mitte 50, eigene Topics und HA-Sensoren. Ausgabe ausdrücklich einschalten; Rate 1–30/s je Achse. <code>ABS_Z</code> wird ignoriert. L1/R1, L2/R2 und Stick-Klicks wie normale Tasten anlernen; L2/R2 sind digital. Zuordnung am Gerät gemessen, neue MQTT-Verarbeitung lokal geprüft; kein allgemeines Profil für jedes Gamepad. Weitere Praxisprüfungen sind in der Roadmap dokumentiert.</li></ul><h2 id="release-031" tabindex="-1">Bereits in 0.1.31: Logitech Touchpad T650, Geräte und sicherer Installer <a class="header-anchor" href="#release-031" aria-label="Permalink to &quot;Bereits in 0.1.31: Logitech Touchpad T650, Geräte und sicherer Installer {#release-031}&quot;">​</a></h2><p>0.1.31 enthält auch die zuvor lokalen Änderungen aus 0.1.29 und 0.1.30. Unter <strong>Tasten &amp; Anzeigen</strong> sind Geräte alphabetisch gruppiert und zunächst eingeklappt. Jeweils nur eine Gerätegruppe und eine Taste ist geöffnet. Lautstärke-, Bildschirmhelligkeits- und Tastaturlichttasten bieten unter <strong>Bearbeiten</strong> den Schrittfilter 1–5: bei 3 werden Schritt 3, 6, 9 usw. gesendet. Loslassen stoppt die Lautstärke-Haltewiederholung auch bei übersprungenen Schritten.</p><p>Eindeutige Seriennummern und verfügbare Logitech-HID++-Kennungen erhalten die Gerätezuordnung beim Umstecken. Ohne eindeutige Kennung das neue USB-Gerät einem gespeicherten Offline-Gerät zuordnen; vorhandene Tasten, Seiten und Topics bleiben. Entfernen über den Papierkorb verlangt eine Bestätigung und sichert Metadaten; gemeinsame Icons bleiben erhalten. Mobile-Vertrauen wird separat widerrufen.</p><h3 id="t650" tabindex="-1">Logitech Touchpad T650: Ein-Finger-Slide und X/Y <a class="header-anchor" href="#t650" aria-label="Permalink to &quot;Logitech Touchpad T650: Ein-Finger-Slide und X/Y {#t650}&quot;">​</a></h3><p>Unter <strong>USB / Virtuelle Geräte</strong> das T650 freigeben, <strong>Touchpad-Gesten auswerten</strong> einschalten und <strong>Ein-Finger-Slide und optionale X/Y-Werte</strong> öffnen. Empfindlichkeit und Senderate einstellen, speichern und danach die gewünschten Richtungen anlernen. Der Linux-Treiber muss Type-B-Multitouch liefern; ein bloßes Klickereignis reicht nicht.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Bewegung</th><th>Anlernbare Aktion</th></tr></thead><tbody><tr><td>Links / rechts</td><td><code>TOUCHPAD_SLIDE_LEFT</code> / <code>TOUCHPAD_SLIDE_RIGHT</code></td></tr><tr><td>Oben / unten</td><td><code>TOUCHPAD_SLIDE_UP</code> / <code>TOUCHPAD_SLIDE_DOWN</code></td></tr><tr><td>Links oben / rechts oben</td><td><code>TOUCHPAD_SLIDE_UP_LEFT</code> / <code>TOUCHPAD_SLIDE_UP_RIGHT</code></td></tr><tr><td>Links unten / rechts unten</td><td><code>TOUCHPAD_SLIDE_DOWN_LEFT</code> / <code>TOUCHPAD_SLIDE_DOWN_RIGHT</code></td></tr></tbody></table></div><p>Acht 45°-Sektoren unterscheiden die Richtungen. Die <strong>Empfindlichkeit 1–10</strong> legt die nötige Bewegung fest: 10 empfindlicher, 1 größere Bewegung; Standard 5. Die <strong>Senderate 1–30/s</strong> ist eine Obergrenze je Richtungsaktionsstrom und X/Y-Paar, Standard 10/s. Ein X/Y-Paar sind zwei MQTT-Nachrichten je Zielbroker; zusätzliche aktivierte Tastenkanäle können weitere Nachrichten erzeugen.</p><p><strong>X/Y ist standardmäßig aus.</strong> Bei Aktivierung werden beim Speichern lesbare Topics angelegt, etwa <code>t650-touchpad/x</code> und <code>t650-touchpad/y</code>. Eigene Topics sind möglich; gespeicherte Topics bleiben bei Umbenennung erhalten. Beide Achsen nutzen die Geräte-Zielbroker und senden reine ganze Zahlen <strong>0–100</strong>, kein JSON. X: links 0, rechts 100; Y: oben 0, unten 100. Das ist die absolute Touchpad-Position.</p><p>Nach erkanntem Slide entsteht beim Abheben kein zusätzlicher Tipp. Unveränderte Positionen werden nicht erneut gesendet. Ein letzter ausstehender Wert darf nach dem Abheben im nächsten erlaubten Intervall folgen. Mehrfingerkontakt, mechanischer Klick, Eingabeverlust oder Optionsänderung verwerfen ausstehende Werte. Kein Retain, kein Nachsenden an zuvor getrennte Broker; im Anlernmodus bleibt X/Y stumm.</p><h3 id="t650-test" tabindex="-1">Logitech Touchpad T650: Praxistest und Grenzen <a class="header-anchor" href="#t650-test" aria-label="Permalink to &quot;Logitech Touchpad T650: Praxistest und Grenzen {#t650-test}&quot;">​</a></h3><p>Am 22. November 2026 auf einem Raspberry Pi 4 (64 Bit) mit echtem T650:</p><ul><li>Alle acht erwarteten Richtungen erkannt; <strong>kein Tipp</strong> in den Slide-Phasen. Separates Tippen erzeugte vier Tipps und keine X/Y-Ausgabe.</li><li>Drei lokale MQTT-Testbroker erhielten jeweils <strong>752 identische Nachrichten</strong>, darunter 200 X/Y-Paare. Achsenwerte sind reine Zahlen innerhalb 0–100.</li><li><strong>Live</strong>: Empfindlichkeit 5, Rate maximal 10/s; kleinster Abstand 0,100000 s.</li><li><strong>Replay derselben echten Aufnahmen</strong>: Empfindlichkeit 1/5/10 ergab bei schnellen Bewegungen 33/38/39 Slide-Aktionen. Rate 1/5/30 ergab minimale X/Y-Abstände von 1,006229 / 0,201979 / 0,037912 s. Das ersetzt keinen zusätzlichen Live-Test der Web-Einstellung oder neuer Handbewegungen mit jedem Wert.</li><li>Zwei benachbarte Richtungsereignisse und einmal Halten wurden mitprotokolliert. Keine Garantie ausschließlich einer Richtung für jede Handbewegung und kein allgemeiner Hardware-Nachweis für andere Mehrfingergesten oder Touchpad-Modelle.</li><li>Nur das T650 wurde ausgewertet; K400/T400 blieben unverändert. Die isolierte Messung nutzte temporäre Einstellungen und Loopback-Broker, keine produktiven Ziele.</li></ul><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/v0.1.31/docs/tests/t650-0.1.31-20261122.md" target="_blank" rel="noreferrer">Vollständiger T650- und Installationsbericht</a>. Das Messwerkzeug wurde ebenfalls korrigiert: begrenztes Pufferleeren konsumiert den evdev-Generator; sichtbarer Start und Sekundenanzeige verhindern unklare Wartephasen.</p><h3 id="installer-031" tabindex="-1">Installer-Korrektur und Datenerhalt <a class="header-anchor" href="#installer-031" aria-label="Permalink to &quot;Installer-Korrektur und Datenerhalt {#installer-031}&quot;">​</a></h3><p>Eine vererbte <code>umask 077</code> konnte die neue Python-Umgebung für das Dienstkonto unzugänglich machen (<code>Permission denied</code> in Schritt 6). Der Installer setzt jetzt <code>umask 022</code> für Programmdateien und <code>umask 077</code> für private Sicherungsarchive. Keine pauschale Rechteänderung an Nutzdaten nötig.</p><p>Die anschließende Installation ist auf dem Pi bestätigt: CLI und laufender Dienst melden <strong>0.1.31</strong>, USB/MQTT und Web sind aktiv, beide mit <strong>NRestarts=0</strong>. Mobile ist aktiv, die Fehlerliste leer. Fünf SHA256-Prüfungen für <code>config.json</code>, <code>switches.json</code>, <code>mobile-identity.json</code>, <code>mobile-trust.json</code> und <code>mobile-devices.json</code> bestätigen bytegleich erhaltene Einstellungen und Kopplungen. Vorab wurde gesichert. Dies ist eine Dienststartprüfung, kein zusätzlicher Langzeittest nach Installation.</p><h2 id="hardware" tabindex="-1">Welche Geräte werden erkannt? <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Welche Geräte werden erkannt? {#hardware}&quot;">​</a></h2><p><strong>Erkannt</strong> bedeutet zunächst: Linux kann das USB-Gerät auflisten. <strong>Bedienbar</strong> bedeutet zusätzlich: Ein Treiber kann seine Eingaben lesen und das Gerät ist in der Oberfläche ausdrücklich freigegeben. Das ist nicht dasselbe.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Gerät</th><th>Was bereits vorgesehen ist</th><th>Prüfstand</th></tr></thead><tbody><tr><td>USB-Tastaturen, auch Windows-Medientastaturen</td><td>Tastencodes, Drücken/Loslassen, Umschalter, Tastenzustand, Klick/Doppelklick/Halten</td><td>Trust-/HCT-Tastaturen im Praxisaufbau genutzt</td></tr><tr><td>Lautstärke- und Medientasten</td><td><code>KEY_VOLUMEUP</code>, <code>KEY_VOLUMEDOWN</code>, <code>KEY_MUTE</code>; weitere vom Gerät gelieferte Play-/Titeltasten</td><td>Lautstärke/Stumm beobachtet; andere Tasten je Modell testen</td></tr><tr><td>HID-Makropads und USB-Fußtaster</td><td>Gleiche Verarbeitung, wenn Linux normale Tastencodes meldet</td><td>Modellabhängig; Rückmeldungen willkommen</td></tr><tr><td>USB-HID-Barcode-/QR-Scanner</td><td>Text-MQTT und native HA-Tag-Discovery</td><td>Aplic 305045 mit Barcode-Wiederholung, Text-QR und HA-Tag praktisch bestätigt</td></tr><tr><td>DragonRise-Gamepad 0079:0006</td><td>Vier Stickwerte 0–100 und normale Tasten</td><td>Hardwarezuordnung gemessen, neue MQTT-Verarbeitung lokal geprüft</td></tr><tr><td>Logitech Touchpad T650</td><td>Acht Slide-Richtungen, optionale Werte/X/Y, alternativ fünf senkrechte Regler</td><td>Richtungen/X/Y in HA, fünf Reglerwerte in ioBroker bestätigt; Prüfgrenzen siehe oben</td></tr><tr><td>Physische Elgato Stream Decks</td><td>Eigener HID-Treiber, Display- und Bedienfunktionen unten</td><td>Implementiert, noch kein physischer Stream-Deck-Test dieses Projekts</td></tr><tr><td>Andere Geräte mit LCD-Tasten</td><td>Tastencodes eventuell über HID; Displayfunktionen brauchen den passenden Herstellertreiber</td><td>Keine allgemeine Kompatibilitätszusage</td></tr><tr><td>Drucker, Kameras, USB-Speicher, Audiointerfaces, serielle Geräte und weitere Controller</td><td>Bestandsanzeige; besondere Nutzfunktionen brauchen eigene Adapter</td><td>Keine allgemeine Druck-, Kamera-, Audio-, MIDI- oder serielle Weiterleitung</td></tr><tr><td>Stream Deck Mobile / Android-App</td><td>Optionaler experimenteller Netzwerkserver mit QR-Kopplung, Bildern und MQTT</td><td>Kopplung, Iconübertragung, Farben und 8×8-Raster vom Nutzer bestätigt; Langzeitstabilität noch offen</td></tr></tbody></table></div><p>Ein angezeigtes Gerät ist nicht automatisch aktiviert. Unter <strong>USB / Virtuelle Geräte</strong> kannst du einen Namen vergeben, <strong>Gerät für Eingaben freigeben</strong> wählen und die Zielbroker ankreuzen. Eindeutige Serien-/Gerätekennungen sind portunabhängig; ohne solche Kennung beim Umstecken ausdrücklich einem gespeicherten Offline-Gerät zuordnen.</p><p><a href="/images/usb-extender/devices.png"><img src="'+i+`" alt="USB-Bestand und ausdrückliche Eingabefreigabe"></a></p><h2 id="installation" tabindex="-1">Installation auf dem Pi <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation auf dem Pi {#installation}&quot;">​</a></h2><p>Empfohlen sind Raspberry Pi 4 und Raspberry Pi OS Lite <strong>64 Bit, Bookworm oder neuer</strong>, Python 3.11+, systemd, sudo sowie Internet für apt/PyPI. Mehrere Geräte mit Displays benötigen gegebenenfalls einen aktiven USB-Hub mit eigener Versorgung. 32-Bit-Pi-OS ist noch nicht praktisch bestätigt.</p><p>ZIP auf den Pi kopieren, im Terminal in den Downloadordner wechseln und ausführen:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.38-Raspi4.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.38</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Der Installer zeigt neun Schritte, prüft Abhängigkeiten und installiert Fehlendes. Bei Updates sichert er vorhandene Daten unter <code>/var/backups/</code>; Einstellungen und Icons bleiben erhalten. Das ZIP ist kein vollständig offline nutzbares Systemabbild. Für spätere Updates das neue ZIP separat entpacken und dessen Installer ausführen.</p><p>Beim ersten Einrichten ein Webpasswort setzen; es gibt kein installiertes Standardpasswort. Falls nötig: <code>sudo usb-extender password</code>. Dann:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Im Browser <code>http://&lt;IP-des-Pi&gt;:8098</code> öffnen und anmelden. Die Beispieladressen auf den Bildern durch die eigenen Brokeradressen ersetzen. HTTP nur im vertrauten lokalen Netz verwenden, ansonsten VPN/HTTPS davor setzen; nicht ins Internet freigeben.</p><h2 id="setup" tabindex="-1">Broker einrichten und Tasten anlernen <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Broker einrichten und Tasten anlernen {#setup}&quot;">​</a></h2><ol><li>Unter <strong>MQTT-Broker</strong> Host, Port und gegebenenfalls Zugangsdaten eintragen. Gewünschte Verbindungen aktivieren und speichern. Pro Broker arbeitet eine eigene Verbindung; eine Taste kann alle drei Ziele erreichen.</li><li>Auf HA-Brokern Discovery aktivieren. Für ioBroker <strong>Aus – nur MQTT-Daten senden</strong> wählen, damit der HA-Discovery-Adapter nicht über Geräteauslöser klagt.</li><li>Unter <strong>USB / Virtuelle Geräte</strong> Gerät benennen, freigeben, Ziele wählen und speichern.</li><li>Unter <strong>Tasten &amp; Anzeigen</strong> das Gerät wählen und <strong>Anlernen starten</strong> drücken. Jede gewünschte Taste einmal drücken und loslassen. Wiederholte und bereits vorhandene Tasten werden nicht doppelt angelegt.</li><li><strong>Anlernen beenden → Tasten übernehmen → Speichern</strong>. Erst jetzt sind neue Zeilen aktiv. Während des Anlernens sendet das ausgewählte Gerät keine Aktionen.</li><li>Pro Zeile Kanäle abwählen oder Topics/Namen ändern. <strong>Bearbeiten</strong> öffnet Brokerwahl, Switch-Verhalten und Zeitwerte. Neue Zusatzkanäle vorhandener Zeilen bleiben zunächst aus; neu angelernte Zeilen haben alle Kanäle vorbereitet.</li></ol><p><a href="/images/usb-extender/brokers.png"><img src="`+s+'" alt="Drei Brokerplätze im Praxisaufbau"></a></p><p><a href="/images/usb-extender/learning.png"><img src="'+a+'" alt="Anlernmodus mit gewähltem USB-Gerät"></a></p><p>Wird das Browserfenster während des Anlernens geschlossen, endet die Pause spätestens nach 15 Sekunden ohne Rückmeldung. Anlernentwürfe liegen bis zum Übernehmen/Speichern nur im Browser. Bereits gespeicherte Belegungen bleiben erhalten.</p><h2 id="topics" tabindex="-1">Topics und Tastenfunktionen <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics und Tastenfunktionen {#topics}&quot;">​</a></h2><p>Aus Gerätename <strong>Trust1</strong> und Taste <strong>F1</strong> entsteht beispielsweise <code>trust1-key-f1/press</code>. Namen werden MQTT-tauglich geschrieben; Umlaute wie in „Büro“ werden zu <code>buero</code>. Doppelte Gerätenamen bekommen bei Bedarf <code>-2</code>, <code>-3</code> usw. Gespeicherte Topics bleiben bei späterer Umbenennung stabil und haben an allen ausgewählten Brokern denselben Namen. Sie lassen sich einzeln bearbeiten.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Endung hinter <code>trust1-key-f1</code></th><th>Nachricht und Funktion</th></tr></thead><tbody><tr><td><code>/press</code></td><td><code>press</code> sofort beim Drücken</td></tr><tr><td><code>/release</code></td><td><code>release</code> beim Loslassen</td></tr><tr><td><code>/press-plus</code>, <code>/release-plus</code></td><td>Gleiche Aktion, nach 50 ms leere Nachricht auf genau diesem Kanal</td></tr><tr><td><code>/switch</code></td><td>Erster Druck <code>ON</code>, nächster Druck <code>OFF</code>; Loslassen ändert nichts</td></tr><tr><td><code>/state</code></td><td>Gedrückt <code>ON</code>, losgelassen <code>OFF</code></td></tr><tr><td><code>/button</code></td><td>Je nach Bedienung <code>click</code>, <code>double_click</code> oder <code>hold</code></td></tr><tr><td><code>/button-plus</code></td><td>Gleiche Button-Aktion, danach nach 50 ms leer</td></tr><tr><td><code>/click</code>, <code>/double-click</code>, <code>/hold</code></td><td>Die jeweilige einzelne Geste</td></tr></tbody></table></div><p><code>plus</code> wird ausgeschrieben, weil <code>+</code> in MQTT ein Platzhalter ist. Alle elf Kanäle sind einzeln aktivierbar. Nur die Plus-Kanäle werden leer zurückgesetzt; leer bedeutet <strong>nicht</strong> Loslassen. Der Switch-Wert bleibt in <code>switches.json</code> über App-Neustarts erhalten und wird beim Wiederverbinden erneut synchronisiert.</p><p><strong>Klick/Doppelklick/Halten:</strong> Ein Klick wartet das Doppelklick-Fenster ab (Vorgabe 300 ms nach Loslassen). Ein zweiter Klick darin ergibt nur <code>double_click</code>. Halten ab 700 ms ergibt einmal <code>hold</code>, ohne Klick beim Loslassen. Wird der zweite Druck gehalten, ersetzt Hold die wartende Klickfolge. Zeiten sind pro Taste einstellbar. Normale Tastaturwiederholungen zählen nicht als weitere Klicks oder Switch-Betätigungen.</p><p><strong>Lauter/Leiser:</strong> Aktive Press-/Press+-Kanäle können beim Halten wiederholt werden, standardmäßig nach 500 ms alle 150 ms. Loslassen beendet die Wiederholung; zusätzlich gilt ein Sicherheitsstopp nach 30 Sekunden. Die Lautstärkeschrittweite bestimmt deine HA-Automation bzw. ioBroker-Logik. Normale Press-/Release-Kanäle bleiben unabhängig von der verzögerten Button-Erkennung sofort verfügbar.</p><p>Die App sendet Tastenmeldungen mit QoS 0 und ohne Retain. Offline-Eingaben werden nicht nachgesendet. Mehrere aktive Kanäle können mehrere zugeordnete Automationen auslösen; für eine einzelne Funktion den passenden Kanal auswählen.</p><h2 id="integration" tabindex="-1">Anzeige in Home Assistant und ioBroker <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Anzeige in Home Assistant und ioBroker {#integration}&quot;">​</a></h2><p>HA-Discovery fasst alle Tasten unter dem gewählten Gerätenamen mit einer gemeinsamen stabilen Gerätekennung zusammen. Aktionen werden als Geräteauslöser mit Payloadfilter angeboten. Switch und Tastenzustand sind <strong>Binärsensoren</strong>, die Zustände anzeigen; zum Schalten anderer Geräte braucht es eine Automation oder Zuordnung.</p><img src="'+d+'" alt="HA zeigt Switch Ein und Tastenzustand Aus nach dem Loslassen" width="280"><p>Im Nutzerbild ist Switch nach der Betätigung <strong>Ein</strong>, der Tastenzustand nach dem Loslassen <strong>Aus</strong>. Zunächst unbekannte Werte können vor der ersten empfangenen Zustandsmeldung auftreten; das ist kein Nachweis einer defekten Tastenerkennung.</p><details><summary>Bild vor den ersten Zustandsmeldungen</summary><img src="'+l+'" alt="HA-Zustände vor den ersten empfangenen Tastenwerten" width="280"></details><p>In ioBroker entstehen unter dem MQTT-Adapter einzelne Datenpunkte, sobald die jeweiligen Topics erstmals empfangen werden. Das Praxisbild zeigt einfache Werte wie <code>press</code>, <code>release</code>, <code>click</code>, <code>hold</code>, <code>ON</code> und <code>OFF</code>. Plus-Kanäle stehen nach der leeren Rücksetzung hier auf <code>(null)</code>. Das ist erwartbar; der Datenpunkt bleibt bestehen. Ein Doppelklick-Datenpunkt erscheint erst, wenn tatsächlich eine passende Nachricht gesendet wurde. Alte Datenpunkte mit dem früheren JSON-Ereigniswert ändern sich nicht automatisch. Discovery-Konfigurationen bleiben absichtlich JSON.</p><p><a href="/images/usb-extender/iobroker-states.png"><img src="'+o+'" alt="Einzelne Datenpunkte mit einfachen Werten in ioBroker"></a></p><h2 id="stream-deck" tabindex="-1">Stream Deck und ähnliche Geräte <a class="header-anchor" href="#stream-deck" aria-label="Permalink to &quot;Stream Deck und ähnliche Geräte {#stream-deck}&quot;">​</a></h2><p>Der integrierte <code>python-elgato-streamdeck</code>-Treiber 0.10.0 kennt unter anderem Original/MK.2, Mini, XL, Neo, Pedal und Plus. Diese Modellliste beschreibt den Treiberumfang, <strong>keinen bereits durchgeführten Hardwaretest</strong> dieses Projekts.</p><ul><li>Displaytasten: eigene Icons und Text, Helligkeit pro Gerät, MQTT-Zustandsrückmeldung zum Wechseln eines Icons und gezielte Displayaufträge.</li><li>Tasten: Press/Release, Klick/Doppelklick/Hold, Switch und Tastenzustand wie oben.</li><li>Drehregler, wenn vorhanden: Drehrichtung und Druck als Eingaben.</li><li>Touchscreen, wenn vorhanden: Touch-Ereignisse; kein frei gestaltbarer Touchscreen-Editor.</li><li>Pedal und andere Modelle ohne Display: Eingaben, aber keine Display-Icons.</li><li>Bis zu acht eigene Seiten je Deck mit Navigationstasten; zusätzliche Profile bleiben offen. Animierte Tastenicons sind implementiert.</li></ul><h3 id="editor" tabindex="-1">Grafischer Editor und kompakte Tastenliste <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Grafischer Editor und kompakte Tastenliste {#editor}&quot;">​</a></h3><p>Der Tab <strong>Stream Deck</strong> bleibt offline sichtbar und erhält Editor und letztes Raster. Gerät freigeben und speichern, dann eine Taste auswählen: Beschriftung, Icon, Hintergrundbild, Textposition und Farben bearbeiten. Für <strong>gedrückt</strong> gibt es ein zweites Icon und eigene Text-/Hintergrundfarben. Text oben/unten erhält Platz neben dem eingepassten Icon. Die Vorschau sendet keine MQTT-Aktion. Danach speichern.</p><p><a href="/images/usb-extender/editor-022.png"><img src="'+u+'" alt="Editor mit simuliertem Deck"></a></p><p>Dieses Bild zeigt eine <strong>lokale Browser-Demo</strong>, keinen Hardwaretest. In <strong>Tasten &amp; Anzeigen</strong> steht eingeklappt nur <strong>Gerät – Key – Name</strong>; immer nur eine Taste ist aufgeklappt. <strong>Speichern</strong> sichert alle ausstehenden Änderungen, <strong>Abbrechen</strong> verwirft nur die Änderungen dieser Taste. Hinweise markieren ungespeicherte Änderungen. <strong>Bearbeiten</strong> öffnet erweiterte MQTT- und Zeitoptionen.</p><h2 id="pages" tabindex="-1">Seiten und Navigation auf dem Deck <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Seiten und Navigation auf dem Deck {#pages}&quot;">​</a></h2><p><strong>USB / Virtuelle Geräte</strong> fasst USB-Geräte und gekoppelte Mobile-Decks zusammen. Handy und Tablet behalten jeweils ihre eigenen Seiten, Gestaltung und Zuordnungen.</p><ol><li>Im Tab <strong>Stream Deck</strong> mit <strong>Neue Seite</strong> bis zu acht Seiten je Gerät anlegen. Die Tasten zählen weiter: bei 15 Tasten 1–15, danach 16–30; bei 8×8 1–64, danach 65–128. Das Raster kommt weiterhin vom Gerät bzw. der Android-App.</li><li>Taste auswählen und unter <strong>Gestaltung → Tastenfunktion</strong> MQTT, <strong>Vor</strong>, <strong>Zurück</strong>, <strong>Home</strong> oder <strong>Gehe zu</strong> wählen. Bei Gehe zu die <strong>Zielseite</strong> wählen. Nach <strong>Speichern</strong> navigieren diese Tasten direkt am Tablet, ohne MQTT-Aktion.</li><li><strong>Seitennummer anzeigen</strong> ergänzt einen kleinen Zähler. Home führt zu Seite 1; Vor/Zurück bleiben an den Grenzen stehen. Die Editorbuttons wechseln nur die Vorschau, nicht die tatsächlich am Gerät sichtbare Seite.</li><li><strong>Aktuelle Seite löschen</strong> entfernt nach Rückfrage deren Belegungen; <strong>Seite 1 ist geschützt</strong>. Erst Speichern übernimmt Änderungen. Andere Seiten behalten ihre IDs/Topics, auch wenn sichtbare Nummern nachrücken. Gehe-zu-Ziele folgen nachrückenden Seiten; beim Löschen des Ziels führt die Taste zu Seite 1.</li></ol><p>Navigation blendet bestehende MQTT-Zuordnungen nur aus; beim Zurückstellen auf MQTT werden sie wieder aktiv. Neue Seiten erhalten stabile Topics wie <code>tablet-page-2-key-0/press</code>; vorhandene Topics der ersten Seite bleiben erhalten. Nach Dienstneustart startet jedes Deck auf Seite 1. Seitenwechsel beenden gehaltene Tasten/Klickfolgen; Rückmeldungen anderer Seiten überschreiben die sichtbare Seite nicht. Farbfelder und übrige Gestaltungsfelder sind kompakter.</p><p><a href="/images/usb-extender/pages-028.png"><img src="'+h+'" alt="Deck-Seiten und kompakte Gestaltung, lokale Simulation"></a></p><h2 id="mobile" tabindex="-1">Stream Deck Mobile: optional und experimentell <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Stream Deck Mobile: optional und experimentell {#mobile}&quot;">​</a></h2><ol><li>Unter <strong>Mobile-Server</strong> aktivieren, erreichbare Pi-Adresse und Port (Standard <strong>28198</strong>) eintragen und speichern.</li><li><strong>Kopplung starten · QR-Code</strong> wählen und in Android mit <strong>Computer hinzufügen</strong> scannen.</li><li>Den sechsstelligen Prüfabdruck vergleichen und nur bei Übereinstimmung unter <strong>Mobile-Verbindungen</strong> auf <strong>Gerät vertrauen</strong> klicken. Vertrauen bleibt gespeichert.</li><li>In Android ein Deck öffnen, das Mobile-Gerät im USB Extender freigeben und speichern. Im Stream-Deck-Editor Gestaltung und MQTT zuordnen.</li><li><strong>Zeilen und Spalten in Android einstellen.</strong> Der Editor übernimmt das gemeldete Raster bis 8×8; keine eigene Rasterübersteuerung.</li></ol><p>Der Mobile-Dienst läuft unabhängig vom Webdienst. Die Weboberfläche wird zum Koppeln benötigt und darf danach abgeschaltet werden. Lokaler WebSocket-Port, keine Cloud-/Bonjour-Erkennung; keine Veränderung der Pro-Kaufberechtigung der App.</p><p><strong>Mobile-Verbindungen</strong> zeigt Bild-/Metadatenzähler, Ping/Pong und letzte Trennung. Bei unveränderten <strong>statischen</strong> Tasten sollen die Bildzähler stehen bleiben. Keepalive hält die Verbindung ohne neue Bilder; Animationen senden absichtlich weitere Bilder. Kopplung, Iconanzeige, Farben und 8×8 wurden vom Nutzer bestätigt. Der unten dokumentierte 15-Minuten-Test mit Navigation und Leerlauf ist bestanden.</p><h3 id="stability" tabindex="-1">0.1.28: erfolgreiche 15-Minuten-Prüfung <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;0.1.28: erfolgreiche 15-Minuten-Prüfung {#stability}&quot;">​</a></h3><p>Bildübertragung wird in kleine Pakete aufgeteilt: maximal vier Bilder je Durchlauf mit einem weichen 25-ms-Arbeitsbudget. Zwischen Paketen werden Eingaben und Heartbeat wieder bedient. Ein bereits laufender Socket-Sendevorgang kann länger dauern; der Heartbeat-Timeout bleibt bei 20 Sekunden. Das Journal enthält bei Trennung zusätzlich Ping/Pong, letzte Nachrichtenart/Alter und ausstehende Bilder, aber keine Nachrichteninhalte oder Zugangsdaten.</p><p>Am <strong>22. November 2026</strong> wurde das echte <strong>SM-T580 mit 8×8 und zwei Seiten</strong> über 900 Sekunden beobachtet: zunächst mehrfach Vor/Zurück, anschließend rund 14 Minuten Leerlauf. Der Monitor wurde vom Nutzer per SSH gestartet; seine 16 Messpunkte und das abschließende Journal wurden direkt ausgewertet.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Messung</th><th>Ergebnis</th></tr></thead><tbody><tr><td>Zeitraum laut Pi-Uhr</td><td>11:39:17–11:54:17; Dauer über monotone Zeit gesteuert</td></tr><tr><td>Tablet-Verbindung</td><td>In allen 16 Messpunkten geöffnet und autorisiert</td></tr><tr><td>Ping/Pong</td><td>56/56 → 232/232; zusätzlich 176 Pings vollständig beantwortet</td></tr><tr><td>Leerlauf</td><td>1.228 Bilder / 19 Metadatenpakete ab Minute 1 unverändert</td></tr><tr><td>Abschließendes Journal</td><td>Kein neuer Heartbeat-Timeout, keine Trennung, kein Dienstneustart</td></tr></tbody></table></div><p>Ein zusätzlicher „connection open“-Eintrag nennt kein Gerät; Tablet-Zähler steigen ohne Rücksetzung weiter. <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/master/docs/tests/mobile-0.1.28-15min-20261122.md" target="_blank" rel="noreferrer">Vollständiger Messbericht</a>. Der Test ist für diesen Zeitraum bestanden. Bildschirmabschaltung, App-Hintergrundbetrieb, andere Netze und physische Stream Decks sind damit nicht geprüft; die Ursache aller früheren Abbrüche ist nicht rückwirkend bewiesen.</p><h2 id="icons" tabindex="-1">Iconbibliothek, Animationen und Paketimport <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Iconbibliothek, Animationen und Paketimport {#icons}&quot;">​</a></h2><p><strong>Grafische Auswahl statt langer Listen:</strong> Bei normalem/gedrücktem Icon, Hintergrund und MQTT-Rückmeldung öffnet sich ein gemeinsamer Picker. Paket aufklappen, suchen, Icon wählen und <strong>Übernehmen</strong> (oder doppelklicken). <strong>Abbrechen</strong>/Escape behalten die vorige Auswahl; danach oben <strong>Speichern</strong>. Die Auswahl lädt nur 48×48-PNG-Miniaturen, bei Animationen das erste Bild, mit höchstens 96 sichtbaren Kacheln je Paketseite. Der Pi erzeugt sie bei Bedarf unter <code>icons/.cache/thumbnails/</code>; Pi und angemeldeter Browser verwenden den Cache.</p><p>Gleiche Icon-IDs/Inhalte erscheinen einmal je Paket; alternative Dateinamen bleiben suchbar. Originale und gespeicherte IDs werden nicht gelöscht oder umgeschrieben; echte Stilvarianten und schwarze/weiße Pakete bleiben getrennt. <strong>MDI-Favoriten hinzufügen · 40 Icons</strong> importiert optional das gebündelte SteelBlue-Paket mit 20 Ein-/Aus-Paaren. Keine automatische Installation oder MQTT-Zuordnung; Normal/Gedrückt bzw. Rückmeldung selbst auswählen.</p><p><a href="/images/usb-extender/picker-028.png"><img src="'+c+'" alt="Grafische Iconauswahl mit Miniaturcache, lokale Demo"></a></p><p>Pakete einzeln aufklappen oder nach Paketname, Dateiname und Unterordner suchen. Hover/Fokus zeigt Namen und Vorschau. 48×48-Miniaturen in 52×52-Kacheln sparen Platz; die Lizenz steht einmal im Paketkopf. Freier und gesamter Speicher stehen im Seitenkopf.</p><p><a href="/images/usb-extender/icons-022.png"><img src="'+g+`" alt="Iconpakete mit Vorschau, lokale Browser-Demo"></a></p><p>Importiert werden Einzelbilder, Browser-Ordner, Ordner auf dem Pi sowie lokale ZIP-, <code>.streamDeckIconPack</code>- und <code>.streamDeckPlugin</code>-Pakete. Bei Plugins werden nur Bilder aus unterstützten Bildordnern übernommen, kein Programmcode. Unterstützte JSON-Metadaten liefern den Paketnamen, sonst gilt der Ordner-/Archivname. Originalnamen und Unterordner bleiben erhalten. Kein automatischer Marketplace-Download; Nutzungsrechte beachten.</p><p>PNG/JPEG und statische SVGs sind unterstützt. GIF/WebP werden <strong>normal und gedrückt</strong> animiert, bis 120 Bilder und höchstens 10 Bilder/s. SVG-Animationen werden nicht abgespielt, Hintergründe bleiben statisch. Reale Hardware muss je Modell geprüft werden.</p><p>Originale: <code>/var/lib/ugso-usbhub/icons/IconPacks/</code>; Index: <code>icons/index.json</code>; abgeleitete Vorschauen: <code>icons/.cache/</code>. Paketlöschen erstellt vorher eine Sicherung und blockiert Pakete mit gespeicherten Zuordnungen.</p><p><strong>Seit 0.1.22:</strong> Index einmal am Ende speichern, Vorschauen und Animationsdaten bei Bedarf erzeugen. Browser-Ordner werden als ein ZIP hochgeladen, auch mit mehreren Paketen und ihren Pfaden. Der Ladebalken nutzt echte Serverzählstände. <strong>Vor einem Update einen laufenden Import fertigstellen lassen.</strong></p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Lokaler Windows-PC-Einzelvergleich</th><th>Vorher</th><th>0.1.22</th></tr></thead><tbody><tr><td>Itsyhome, 240 echte PNGs</td><td>4,262 s</td><td>0,395 s</td></tr><tr><td>6.800 synthetische PNGs</td><td>458,323 s</td><td>10,464 s</td></tr></tbody></table></div><p>Indexschreibvorgänge: vorher 240 beziehungsweise 6.800, danach jeweils einer. Das sind PC-Messwerte, keine Pi-/SD-Kartenmessung. Beim vorherigen Import mit 6.862 Icons erschien bei 2.898 wieder die Loginseite, ohne Fehlermeldung. Nach Einspielen des Updates meldet der Nutzer, dass es wieder funktioniert. Der vollständige Abschluss aller 6.862 Icons ist noch nicht bestätigt.</p><p>Bei Fremdgeräten mit ähnlicher Optik kann der Tastaturteil bereits über HID funktionieren. LCDs, Touch und herstellerspezifische Befehle benötigen eventuell einen eigenen Adapter. Bitte ein konkretes Modell testen und berichten, statt von der äußeren Ähnlichkeit auf vollständige Kompatibilität zu schließen.</p><h2 id="operation" tabindex="-1">Weboberfläche abschalten und sichern <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Weboberfläche abschalten und sichern {#operation}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ugso-usbhub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>web stop</code> beendet den HTTP-Listener; das Schließen des Browsers allein tut das nicht. Der USB-/MQTT-Dienst läuft weiter. Einstellungen, Icons und Switch-Werte liegen unter <code>/var/lib/ugso-usbhub/</code>. Die letzten zehn Konfigurationsstände werden automatisch gesichert; eine vollständige CLI-Sicherung enthält auch Icons und Switch-Werte. Backups nicht öffentlich hochladen.</p><p><a href="/images/usb-extender/system.png"><img src="`+b+'" alt="Systembefehle und Diagnoseseite"></a></p><h2 id="tests" tabindex="-1">Was ist praktisch nachgewiesen? <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Was ist praktisch nachgewiesen? {#tests}&quot;">​</a></h2><p>Die Nutzerbilder zeigen 0.1.5, drei online gemeldete Brokerplätze, angelernte Funktionstasten, HA-Zustände und einzelne ioBroker-Datenpunkte. Im Verlauf ist die Übergabe an HA, IOB und Testserver sichtbar. Die Übergabeanzeige allein beweist keinen Empfang bei jedem Broker; HA-/ioBroker-Bilder liefern den zusätzlichen sichtbaren Nachweis. Nicht jede Funktion ist dadurch an jeder Hardware geprüft.</p><p><a href="/images/usb-extender/events.png"><img src="'+p+'" alt="F12-Ereignisse mit ausgewählten Topics und drei MQTT-Zielen"></a></p><p>Für 0.1.28 bestehen 168 erfolgreiche lokale Python-Tests sowie JavaScript-/DOM- und Chrome-Prüfungen für Seiten, Speichern, mobile Darstellung, Iconauswahl, Pakete und Animationen. Dazu kommt der erfolgreiche reale 15-Minuten-Test oben. Neue/Löschen-Seite, Home und Gehe zu sind lokal geprüft; deren vollständiger Hardwaretest sowie Tests physischer Stream Decks bleiben weitere Prüfpunkte.</p><h2 id="feedback" tabindex="-1">Eigene Hardware testen und Rückmeldung geben <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Eigene Hardware testen und Rückmeldung geben {#feedback}&quot;">​</a></h2><p>Besitzt du ein Stream Deck, ein ähnliches LCD-Tastengerät, Makropad oder USB-Pedal? Teste es gern und <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/issues/new?template=hardware-test.yml" target="_blank" rel="noreferrer">melde deine Ergebnisse auf GitHub</a>. Fehlerberichte und Mitarbeit sind willkommen.</p><p>Bitte Modell/Revision, Pi-Modell, Betriebssystem und App-Version nennen. Unterscheide Bestandsanzeige und echte Tastencodes. Berichte getrennt über Drücken/Loslassen, Klick/Doppelklick/Halten, Icons/Text, Helligkeit, Drehregler, Touch und Wiederanstecken; nicht geprüfte Funktionen ausdrücklich so markieren. Nutze zuerst ein unkritisches MQTT-Topic ohne echte Geräteaktionen. Screenshots von Bestand und Ereignissen helfen. Keine Passwörter, Tokens, <code>config.json</code> oder Sicherungsarchive veröffentlichen.</p>',125)])])}const y=k(T,[["render",B]]);export{F as __pageData,y as default};
